FROM molecule
WHERE label = '+';

387.sql:
SELECT `name`, `colorIdentity`
FROM cards
WHERE `setCode` = 'OGW' AND `colorIdentity` IS NOT NULL;

419.sql:
SELECT COUNT(*) AS answer
FROM cards
WHERE `borderColor` = 'borderless' AND `edhrecRank` > 12000;

