882.sql:
SELECT MIN(year) AS first_year
FROM races
WHERE name = 'Singapore Grand Prix';

996.sql:
SELECT COUNT(*) / (2010 - 2000 + 1) AS annual_average
FROM races
WHERE year BETWEEN 2000 AND 2010;

